\newcommand{\Kstar}{K^{*}}

\title{Generational Depth Contamination Has a Bounded Discrimination Boundary:\\Measuring $K^{*}$ Across Domains, Models, and Decoding Strategies}

\author{Anonymous}

\begin{document}
